<?php declare(strict_types=1);
require __DIR__.'/invoice-mailbox.php';
use Kulturhus\Verein\{InvoiceMailbox, Documents};
$base=$n;$n=0;
$db->exec("INSERT INTO clubs VALUES('purge','Synthetic purge');INSERT INTO actors(id,club_id,role,is_superuser) VALUES('purge-admin','purge','member',1)");
$mailbox=new InvoiceMailbox($db,'purge-admin',str_repeat('synthetic-purge-key',3));
$cfg=array_replace(InvoiceMailbox::defaults(),['email'=>'purge@example.invalid','imap_host'=>'imap.example.test','imap_user'=>'purge@example.invalid','imap_password'=>'synthetic-only','enabled'=>true]);$mailbox->save($cfg,0);
$payload=['uidvalidity'=>1,'messages'=>[['uid'=>1,'subject'=>'Synthetic deletion test','sender'=>'supplier@example.invalid','date'=>'2026-09-01','original'=>"Subject: Synthetic\r\n\r\nTwo wrong attachments",'attachments'=>[['name'=>'one.pdf','bytes'=>'%PDF-1.4 Synthetic one'],['name'=>'two.pdf','bytes'=>'%PDF-1.4 Synthetic two']]]]];
$read=static function()use(&$payload){return $payload;};
$r=$mailbox->fetch($read);ok($r['new']===2,'two fake attachments imported without actual network');
$imports=$mailbox->recent();$docs=new Documents($db,'purge-admin');$first=$imports[0]['document_id'];$second=$imports[1]['document_id'];
$docs->purgeReceipt($first,1,true);
ok((int)$db->query("SELECT COUNT(*) FROM invoice_mail_originals WHERE club_id='purge'")->fetchColumn()===1,'shared original mail retained for other document');
ok($docs->file($second)['bytes']!=='','other attachment remains accessible unchanged');
$docs->purgeReceipt($second,1,true);
foreach(['invoice_mail_imports','invoice_mail_original_links','invoice_mail_originals','document_files','documents'] as $table)ok((int)$db->query("SELECT COUNT(*) FROM $table WHERE club_id='purge'")->fetchColumn()===0,'last purge removes '.$table);
$payload['uidvalidity']=2;$payload['messages'][0]['uid']=1;$r=$mailbox->fetch($read);
ok($r['new']===0&&$r['existing']===2&&$r['failed']===0&&$r['mail_only']===0,'UID reset cannot reimport deliberately purged attachments as documents or mail-only copies');
ok((int)$db->query("SELECT COUNT(*) FROM invoice_mail_originals WHERE club_id='purge'")->fetchColumn()===0,'deduplication does not recreate original mail bytes');
ok(!\Kulturhus\Verein\Tests\MySqlFixture::foreignKeyErrors($db),'purge/mail integration preserves foreign keys');
echo "$n purge/mail checks passed plus $base mailbox checks; fake transport only\n";
